import json,time,numpy as np,onnxruntime as ort,pathlib
root=pathlib.Path('source/magic-conch/research/laya');data=json.loads((root/'shortlist-inputs.json').read_text());opts=ort.SessionOptions();opts.intra_op_num_threads=2;opts.graph_optimization_level=ort.GraphOptimizationLevel.ORT_ENABLE_BASIC
enc=ort.InferenceSession('laya-onnx-packed/encoder.onnx',sess_options=opts);head=ort.InferenceSession('laya-onnx-packed/head.onnx',sess_options=opts);rows=[]
for c,b in zip(data['cases'],data['batches']):
 start=time.perf_counter();mask=np.array(b['attentionMask'],np.int64);hidden=enc.run(None,{'input_ids':np.array(b['inputIds'],np.int64),'attention_mask':mask})[0];logits,act=head.run(None,{'hidden_states':hidden,'marker_pos':np.array(b['markerPos'],np.int64),'marker_mask':np.array(b['markerMask'],np.bool_),'qtype':np.array(b['qtype'],np.int64).reshape(-1,1),'attention_mask':mask});pick=int(logits.argmax());intent=c['candidates'][pick] if pick<len(c['candidates']) else 'NONE';rows.append({**c,'pick':intent,'pass':intent in c['accept'],'ms':(time.perf_counter()-start)*1000})
summary={str(k):{'correct':sum(r['pass'] for r in rows if r['k']==k and r['order']=='forward'),'count':20,'order_agreement':sum(a['pick']==b['pick'] for a,b in zip([r for r in rows if r['k']==k and r['order']=='forward'],[r for r in rows if r['k']==k and r['order']=='reverse']))} for k in [4,8]};(root/'shortlist-results.json').write_text(json.dumps({'split':'development','summary':summary,'rows':rows},ensure_ascii=False,indent=2));print(summary,flush=True)
